(()=>{
const input=document.getElementById('prompt');if(!input)return;
const phrase='地区部、代表处、国家、项目、合同、DU、PL、货龄';
const wrap=document.createElement('div');wrap.className='prompt-emphasis-wrap';input.before(wrap);wrap.append(input);
const overlay=document.createElement('div');overlay.className='prompt-emphasis-layer';overlay.setAttribute('aria-hidden','true');wrap.prepend(overlay);
function render(){const value=input.value,active=value.includes(phrase);wrap.classList.toggle('has-prompt-emphasis',active);overlay.replaceChildren();if(!active)return;const parts=value.split(phrase);parts.forEach((part,i)=>{overlay.append(document.createTextNode(part));if(i<parts.length-1){const mark=document.createElement('span');mark.textContent=phrase;overlay.append(mark)}});overlay.append(document.createTextNode('\n'));const s=getComputedStyle(input);for(const key of ['fontFamily','fontSize','fontWeight','lineHeight','letterSpacing','paddingTop','paddingRight','paddingBottom','paddingLeft','textAlign','textIndent','wordBreak','overflowWrap'])overlay.style[key]=s[key];overlay.scrollTop=input.scrollTop;overlay.scrollLeft=input.scrollLeft}
input.addEventListener('input',render);input.addEventListener('scroll',render);window.addEventListener('resize',render);const base=refreshSend;refreshSend=function(...args){const result=base.apply(this,args);render();return result};new ResizeObserver(render).observe(input);render();
const style=document.createElement('style');style.textContent='.prompt-emphasis-wrap{position:relative;width:100%;min-width:0}.prompt-emphasis-layer{position:absolute;inset:0;z-index:1;box-sizing:border-box;white-space:pre-wrap;pointer-events:none;overflow:hidden;color:#000;visibility:hidden}.prompt-emphasis-layer span{color:#0067D1;font-style:italic}.prompt-emphasis-wrap.has-prompt-emphasis .prompt-emphasis-layer{visibility:visible}body[data-system-theme] .reference-composer .prompt-emphasis-wrap.has-prompt-emphasis #prompt{position:relative;color:transparent!important;-webkit-text-fill-color:transparent!important;caret-color:#000!important;background:transparent!important;text-shadow:none!important}.prompt-emphasis-wrap #prompt{display:block;box-sizing:border-box}.prompt-emphasis-wrap.has-prompt-emphasis #prompt::selection{background:#b5d8ff;color:transparent}';document.head.append(style);
})();
